import { LocalStorage, generateGuid, parseQueryString } from '@game-studio/utilities';

const DEVICE_ID_KEY = 'tombola.device-id';

export function getDeviceId() {
    const queryString = parseQueryString();
    if (queryString.deviceId) {
        LocalStorage.setItem(DEVICE_ID_KEY, queryString.deviceId);
        return queryString.deviceId;
    }

    const localStorageId = LocalStorage.getItem<string>(DEVICE_ID_KEY);
    const deviceId = localStorageId ?? generateGuid();

    if (!localStorageId || localStorageId !== deviceId) {
        LocalStorage.setItem(DEVICE_ID_KEY, deviceId);
    }

    return deviceId;
}